-- 442: Foundation guard for WASSCE Core Mathematics sprint 2 beta batch (wassce-core-math-sprint2-001).
-- Original BrillaPrep practice content; not official WAEC examination material.
-- Re-asserts the prod-canonical topic rows for subj_wassce_core_math on scratch
-- baselines; INSERT OR IGNORE no-ops on prod and on fresh baselines where the
-- rows already exist (prod patch 095 and migration 364).
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO exam_boards (id, name, code, full_name, region, website_url, is_active, display_order) VALUES ('board_waec', 'WAEC', 'WAEC', 'West African Examinations Council', 'West Africa', 'https://waecgh.org/', 1, 1);
CREATE TABLE IF NOT EXISTS question_content_releases (
    question_id TEXT PRIMARY KEY REFERENCES questions(id) ON DELETE CASCADE,
    batch_id TEXT NOT NULL,
    quality_assurance TEXT NOT NULL CHECK (quality_assurance IN ('automated_beta', 'human_reviewed')),
    release_channel TEXT NOT NULL CHECK (release_channel IN ('beta', 'production')),
    content_label TEXT NOT NULL,
    source_url TEXT NOT NULL,
    official_exam_board_content INTEGER NOT NULL DEFAULT 0 CHECK (official_exam_board_content IN (0, 1)),
    feedback_enabled INTEGER NOT NULL DEFAULT 1 CHECK (feedback_enabled IN (0, 1)),
    released_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
CREATE INDEX IF NOT EXISTS idx_question_content_releases_batch ON question_content_releases(batch_id);
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wcoremath_algebra', 'subj_wassce_core_math', NULL, 'Algebra', 'wcoremath-algebra', 'Manipulate symbols, solve linear and simultaneous equations and rearrange formulae.', 'Algebraic fluency underpins WASSCE Core Mathematics: collect like terms, expand and factorise expressions, solve linear and simultaneous equations, and change the subject of a formula.', '["ax + b = c → x = (c − b)/a", "(a + b)² = a² + 2ab + b²", "a² − b² = (a + b)(a − b)"]', 1, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wcoremath_quadratic', 'subj_wassce_core_math', NULL, 'Quadratic Equations', 'wcoremath-quadratic', 'Solve and analyse quadratic equations and their roots.', 'Quadratic equations are solved by factorisation, completing the square or the formula; the discriminant b² − 4ac determines the nature of the roots.', '["x = (−b ± √(b² − 4ac))/2a", "sum of roots = −b/a", "product of roots = c/a", "equal roots ⇔ b² − 4ac = 0"]', 2, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wcoremath_geometry', 'subj_wassce_core_math', NULL, 'Geometry', 'wcoremath-geometry', 'Apply properties of angles, triangles, polygons and circles to measurements.', 'Geometry covers angle relationships, properties of triangles and polygons, and circle theorems used to calculate unknown angles and lengths.', '["Angles in a triangle sum to 180°", "Angles on a straight line sum to 180°", "Exterior angles of a polygon sum to 360°", "Angle at centre = 2 × angle at circumference"]', 3, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wcoremath_trigonometry', 'subj_wassce_core_math', NULL, 'Trigonometry', 'wcoremath-trigonometry', 'Use trigonometric ratios and identities for right-angled triangles.', 'Trigonometry relates the sides and angles of right-angled triangles through sine, cosine and tangent, together with the theorem of Pythagoras.', '["sin θ = opposite/hypotenuse", "cos θ = adjacent/hypotenuse", "tan θ = opposite/adjacent", "sin²θ + cos²θ = 1", "a² + b² = c²"]', 4, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wcoremath_statistics', 'subj_wassce_core_math', NULL, 'Statistics & Probability', 'wcoremath-statistics', 'Analyse data with averages and compute probabilities of events.', 'Statistics summarises data with the mean, median, mode and range; probability measures the likelihood of equally likely outcomes.', '["Mean = Σx/n", "Range = largest − smallest", "P(event) = favourable outcomes/total outcomes"]', 5, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_math_num', 'subj_wassce_core_math', NULL, 'Number and numeration', 'wassce-p2-math-num', 'Apply percentages, fractions and ratio reasoning to everyday situations.', 'Number and numeration covers fractions, decimals, percentages, approximation, HCF/LCM, ratio sharing and commercial arithmetic such as profit, loss and simple interest.', '["Percentage profit = profit/cost price × 100", "Simple interest = PRT/100", "a% of N = (a/100) × N"]', 6, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_math_men', 'subj_wassce_core_math', NULL, 'Mensuration', 'wassce-p2-math-men', 'Calculate perimeters, areas, surface areas and volumes of plane figures and solids.', 'Mensuration applies standard formulas for the perimeter and area of plane figures and the surface area and volume of cuboids, cubes and cylinders, often with a stated value of π.', '["Area of rectangle = l × w", "Area of triangle = ½bh", "Area of circle = πr²", "Circumference = 2πr", "Volume of cylinder = πr²h", "Surface area of cube = 6a²"]', 7, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_math_rat', 'subj_wassce_core_math', NULL, 'Ratio and proportion', 'wassce-p2-math-rat', 'Simplify ratios and share quantities; solve direct and inverse proportion problems.', 'Ratio and proportion covers simplifying ratios, sharing a quantity in a given ratio, unitary-method problems, map scales, and direct and inverse variation in everyday contexts.', '["Share in ratio a : b → total parts = a + b", "Scale 1 : n → actual = map × n", "Inverse proportion → workers × days is constant"]', 8, '2026-08-04T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_wassce_p2_math_prb', 'subj_wassce_core_math', NULL, 'Probability', 'wassce-p2-math-prb', 'Compute probabilities of single and compound events.', 'Probability measures likelihood on a scale from 0 to 1 using equally likely outcomes; compound events combine single-event probabilities by multiplication (independent) or addition (mutually exclusive), with or without replacement.', '["P(event) = favourable outcomes/total outcomes", "P(not A) = 1 − P(A)", "P(A and B) = P(A) × P(B) for independent events"]', 9, '2026-08-04T00:00:00.000Z');
CREATE TABLE IF NOT EXISTS _migration_442_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_442_guard;
INSERT INTO _migration_442_guard(valid) SELECT CASE WHEN EXISTS (SELECT 1 FROM exam_types WHERE id = 'exam_wassce') AND EXISTS (SELECT 1 FROM exam_boards WHERE id = 'board_waec') AND EXISTS (SELECT 1 FROM subjects WHERE id = 'subj_wassce_core_math' AND exam_type_id = 'exam_wassce') AND (SELECT COUNT(*) FROM topics t JOIN subjects s ON s.id = t.subject_id WHERE t.id IN ('topic_wcoremath_algebra', 'topic_wcoremath_quadratic', 'topic_wcoremath_geometry', 'topic_wcoremath_trigonometry', 'topic_wcoremath_statistics', 'topic_wassce_p2_math_num', 'topic_wassce_p2_math_men', 'topic_wassce_p2_math_rat', 'topic_wassce_p2_math_prb') AND t.subject_id = 'subj_wassce_core_math' AND s.exam_type_id = 'exam_wassce') = 9 THEN 1 ELSE 0 END;
DROP TABLE _migration_442_guard;
